"use strict";let Input,{cyan:cyan,gray:gray,green:green,yellow:yellow,magenta:magenta}=require("colorette"),tokenizer=require("./tokenize");function registerInput(e){Input=e}const HIGHLIGHT_THEME={brackets:cyan,"at-word":cyan,comment:gray,string:green,class:yellow,hash:magenta,call:cyan,"(":cyan,")":cyan,"{":yellow,"}":yellow,"[":yellow,"]":yellow,":":yellow,";":yellow};function getTokenType([e,n],t){if("word"===e){if("."===n[0])return"class";if("#"===n[0])return"hash"}if(!t.endOfFile()){let e=t.nextToken();if(t.back(e),"brackets"===e[0]||"("===e[0])return"call"}return e}function terminalHighlight(e){let n=tokenizer(new Input(e),{ignoreErrors:!0}),t="";for(;!n.endOfFile();){let e=n.nextToken(),r=HIGHLIGHT_THEME[getTokenType(e,n)];t+=r?e[1].split(/\r?\n/).map(e=>r(e)).join("\n"):e[1]}return t}terminalHighlight.registerInput=registerInput,module.exports=terminalHighlight;